    producer:{reader:'ORIGINAL_SF88_OPEN_QUEUE_SHOW',outputReader:'ORIGINAL_SF88_INBOX_RESPONSE_VERIFY',
      noExecution:true,maxVerifyBytes,verifiedBytes:totalVerified}};
