    resolve(directory) === directory && !directory.includes('\0') &&
    typeof filename === 'string' && /^[.a-zA-Z0-9_-]{1,120}\.lock$/.test(filename) &&
    typeof namespace === 'string' && /^[a-zA-Z0-9_-]{1,80}$/.test(namespace),
  unavailableCode);
