"""Receive the retained GIS source and customer, then run their original operation."""
from __future__ import annotations

import argparse
import ast
from datetime import datetime, timezone
import gzip
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import stat
import subprocess
import sys
import tempfile
import tomllib
import urllib.request
import zipfile

OPERATION = "SCF-DUCKDB-GIS-CUSTOMER-5EEE-20261012"
SOURCE_COMMIT = "ba078c26cf05dda1f44044eaaecb948971caaae9"
SOURCE_SHA256 = "6cb31aecf95d5a4b6eafb3879066e80332dbcb8c0b2f552dec029f1d3f2ece66"
CUSTOMER_SHA256 = "50ea5a14216db46bdb8d31980ce9d7fc7f45cd4897184a3befa88ed72004f369"
WAREHOUSE_SHA256 = "aa7182fee4cbfc5dd4e56468bab2ab5734682f2db5af0adc79884f9e310ee656"
CUSTOMER_ROOT = "SCF_DuckDB_Customer_Receiving_20261012"
EXTENSION_URL = "https://extensions.duckdb.org/v1.5.6/linux_amd64/spatial.duckdb_extension.gz"


def private(path):
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o077:
        raise RuntimeError("Receiving directory must be private: " + str(path))
    return path


def identity(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode):
            raise RuntimeError("Expected a regular source file")
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
        after = os.fstat(stream.fileno())
        if (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns) != (
                after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
            raise RuntimeError("Source changed during receiving")
        return {"bytes": info.st_size, "sha256": digest}


def publish(path, content):
    private(path.parent)
    if path.exists() or path.is_symlink():
        if identity(path) != {"bytes": len(content), "sha256": hashlib.sha256(content).hexdigest()}:
            raise RuntimeError("Existing receiving source differs: " + str(path))
        return
    fd, temporary = tempfile.mkstemp(prefix=".source-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary, path, follow_symlinks=False)
    finally:
        os.unlink(temporary)


def save(path, value):
    private(path.parent)
    if path.exists():
        before = json.loads(path.read_text())
        if before.get("operation") != OPERATION:
            raise RuntimeError("Receiving record belongs to another operation")
    fd, temporary = tempfile.mkstemp(prefix=".record-", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, indent=2)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def relative(name):
    path = PurePosixPath(name)
    if not name or "\\" in name or path.is_absolute() or ".." in path.parts or str(path) != name.rstrip("/"):
        raise RuntimeError("Invalid receiving member path")
    return path


def receive_source(capsule, package):
    if identity(capsule) != {"bytes": 1450855, "sha256": SOURCE_SHA256}:
        raise RuntimeError("Original source capsule differs")
    payload = json.loads(capsule.read_text(encoding="utf-8"))
    if (payload.get("schema"), payload.get("operation_id"), payload.get("repository"), payload.get("source_commit")) != (
            "scf.portable-python-source/1", OPERATION, "woahwhattheheck/public-commons-sprint-2026", SOURCE_COMMIT):
        raise RuntimeError("Original source identity differs")
    files = payload["files"]
    if len(files) != 67 or len({item["path"] for item in files}) != 67:
        raise RuntimeError("Complete original source inventory required")
    for item in files:
        name = relative(item["path"])
        raw = item["content"].encode("utf-8")
        if item["encoding"] != "utf-8" or len(raw) != item["bytes"] or hashlib.sha256(raw).hexdigest() != item["sha256"]:
            raise RuntimeError("Source file digest differs")
        if hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest() != item["git_blob_sha"]:
            raise RuntimeError("Source Git blob differs")
        if name.suffix == ".py":
            ast.parse(item["content"], filename=item["path"])
        publish(package / str(name), raw)
    project = tomllib.loads((package / "pyproject.toml").read_text())
    if "duckdb==1.5.6" not in project["project"]["optional-dependencies"]["duckdb"]:
        raise RuntimeError("Pinned native engine declaration differs")
    return {"commit": SOURCE_COMMIT, "capsule": identity(capsule), "files": len(files)}


def receive_customer(archive, destination):
    if identity(archive) != {"bytes": 282686, "sha256": CUSTOMER_SHA256}:
        raise RuntimeError("Original customer archive differs")
    with zipfile.ZipFile(archive) as source:
        members = source.infolist()
        if len(members) != 48 or len({item.filename for item in members}) != 48:
            raise RuntimeError("Original customer member inventory differs")
        if sum(item.file_size for item in members) > 512 * 1024 * 1024:
            raise RuntimeError("Customer archive exceeds receiving budget")
        for item in members:
            name = relative(item.filename)
            mode = item.external_attr >> 16
            if name.parts[0] != CUSTOMER_ROOT or stat.S_ISLNK(mode) or item.flag_bits & 1:
                raise RuntimeError("Invalid original customer member")
            target = destination / str(name)
            if item.is_dir():
                private(target)
            else:
                publish(target, source.read(item))
    original = destination / CUSTOMER_ROOT / "arcgis" / "workspace"
    record = identity(original / "warehouse.duckdb")
    if record != {"bytes": 11808768, "sha256": WAREHOUSE_SHA256}:
        raise RuntimeError("Original closed ArcGIS warehouse differs")
    return original, {"archive": identity(archive), "warehouse": record, "members": len(members)}


def engine(python):
    try:
        result = subprocess.run([python, "-B", "-c",
            "import sys,duckdb,json; print(json.dumps({'python':sys.version.split()[0],'duckdb':duckdb.__version__}))"],
            stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=30)
        value = json.loads(result.stdout)
        if result.returncode == 0 and value.get("duckdb") == "1.5.6" and tuple(map(int, value["python"].split(".")[:2])) >= (3, 11):
            return value
    except (OSError, ValueError, subprocess.SubprocessError):
        pass
    return None


def download_extension(target):
    private(target.parent)
    if target.exists():
        return identity(target)
    request = urllib.request.Request(EXTENSION_URL, headers={"Accept-Encoding": "identity"})
    fd, temporary = tempfile.mkstemp(prefix=".spatial-", dir=target.parent)
    try:
        with os.fdopen(fd, "wb") as output, urllib.request.urlopen(request, timeout=180) as response:
            if response.status != 200 or not response.geturl().startswith("https://extensions.duckdb.org/"):
                raise RuntimeError("Official extension response differs")
            declared = response.headers.get("Content-Length")
            total = 0
            while True:
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                total += len(chunk)
                if total > 128 * 1024 * 1024:
                    raise RuntimeError("Compressed extension exceeds receiving budget")
                output.write(chunk)
            if not total or (declared is not None and total != int(declared)):
                raise RuntimeError("Incomplete official extension")
            output.flush()
            os.fsync(output.fileno())
        os.link(temporary, target, follow_symlinks=False)
        return identity(target)
    finally:
        os.unlink(temporary)


def unpack_extension(compressed, target):
    fd, temporary = tempfile.mkstemp(prefix=".extension-", dir=target.parent)
    try:
        total = 0
        with os.fdopen(fd, "wb") as output, gzip.open(compressed, "rb") as source:
            while True:
                chunk = source.read(1024 * 1024)
                if not chunk:
                    break
                total += len(chunk)
                if total > 512 * 1024 * 1024:
                    raise RuntimeError("Spatial extension exceeds receiving budget")
                output.write(chunk)
            output.flush()
            os.fsync(output.fileno())
        record = identity(Path(temporary))
        if target.exists() or target.is_symlink():
            if identity(target) != record:
                raise RuntimeError("Existing signed extension differs")
        else:
            os.link(temporary, target, follow_symlinks=False)
        return record
    finally:
        os.unlink(temporary)


def deliver(root, package, original_archive, extension, compressed, capsule):
    """Retain the complete received product after its native processes have closed."""
    selected = {}
    for base, prefix in ((package, "python"), (root / "operation", "operation")):
        for directory, directories, filenames in os.walk(base, followlinks=False):
            for name in directories:
                if (Path(directory) / name).is_symlink():
                    raise RuntimeError("Delivery directory changed to a link")
            for name in filenames:
                path = Path(directory) / name
                if name.endswith(".lock") or name in {".lock", "duckdb-launch.json"}:
                    continue
                selected[prefix + "/" + path.relative_to(base).as_posix()] = path
    selected["inputs/" + original_archive.name] = original_archive
    selected["receiving/source-capsule.json"] = capsule
    for name in ("native_spatial_receive.py", "native_spatial_foreground.py", "native_spatial_setup.py", "NATIVE_GIS_RECEIVING.md"):
        helper = Path(__file__).parent / name
        if helper.exists():
            selected["receiving/" + name] = helper
    selected["runtime/" + ("spatial.duckdb_extension.gz" if compressed else "spatial.duckdb_extension")] = compressed or extension
    records = [{"name": name, **identity(path)} for name, path in sorted(selected.items())]
    native = json.loads((root / "operation" / "native-gis-result.json").read_text())
    if native.get("state") != "COMPLETE" or native.get("operation") != OPERATION:
        raise RuntimeError("Complete original native result is required for delivery")
    manifest = {"schema": "stellar-forge.duckdb-gis.received-product.v1", "operation": OPERATION,
                "source_commit": SOURCE_COMMIT, "source_capsule_sha256": SOURCE_SHA256,
                "original_customer_sha256": CUSTOMER_SHA256, "signed_extension": identity(extension),
                "duckdb": "1.5.6", "files": records}
    raw_manifest = (json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode()
    content_id = hashlib.sha256(raw_manifest).hexdigest()
    destination = private(root / "delivery")
    archive = destination / ("SCF_DuckDB_GIS_Customer_" + content_id[:16] + ".zip")
    manifest_path = destination / ("SCF_DuckDB_GIS_Customer_" + content_id[:16] + ".json")
    if archive.exists():
        if manifest_path.read_bytes() != raw_manifest:
            raise RuntimeError("Existing GIS delivery inventory differs")
        with zipfile.ZipFile(archive) as existing:
            if existing.read("manifest.json") != raw_manifest or existing.testzip() is not None:
                raise RuntimeError("Existing GIS delivery differs")
        return {"path": str(archive), **identity(archive), "manifest_sha256": content_id, "reused": True}
    fd, temporary = tempfile.mkstemp(prefix=".delivery-", dir=destination)
    os.close(fd)
    try:
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as output:
            for record in records:
                path = selected[record["name"]]
                item = zipfile.ZipInfo(record["name"], date_time=(1980, 1, 1, 0, 0, 0))
                item.external_attr = (stat.S_IFREG | 0o600) << 16
                item.compress_type = zipfile.ZIP_STORED if path.name.endswith(".gz") else zipfile.ZIP_DEFLATED
                count, digest = 0, hashlib.sha256()
                source_fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
                with os.fdopen(source_fd, "rb") as source, output.open(item, "w", force_zip64=True) as member:
                    while True:
                        chunk = source.read(1024 * 1024)
                        if not chunk:
                            break
                        count += len(chunk)
                        digest.update(chunk)
                        member.write(chunk)
                if count != record["bytes"] or digest.hexdigest() != record["sha256"]:
                    raise RuntimeError("GIS delivery source changed during capture")
            output.writestr("manifest.json", raw_manifest)
        with open(temporary, "rb") as complete:
            os.fsync(complete.fileno())
        os.link(temporary, archive, follow_symlinks=False)
        publish(manifest_path, raw_manifest)
    finally:
        os.unlink(temporary)
    return {"path": str(archive), **identity(archive), "manifest_sha256": content_id, "files": len(records)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", required=True)
    parser.add_argument("--source-capsule", required=True)
    parser.add_argument("--customer-zip", required=True)
    parser.add_argument("--python", default=sys.executable)
    parser.add_argument("--install-runtime", action="store_true")
    parser.add_argument("--spatial-gzip")
    parser.add_argument("--spatial-extension")
    parser.add_argument("--acquire-spatial", action="store_true")
    parser.add_argument("--chromium")
    parser.add_argument("--node")
    parser.add_argument("--playwright")
    args = parser.parse_args()
    root = private(Path(args.root).absolute())
    result = {"schema": "stellar-forge.duckdb-gis.receiving.v1", "operation": OPERATION,
              "source_commit": SOURCE_COMMIT, "started_at": datetime.now(timezone.utc).isoformat()}
    try:
        package = private(root / "python")
        result["source"] = receive_source(Path(args.source_capsule), package)
        original, result["customer"] = receive_customer(Path(args.customer_zip), private(root / "customer"))
        python = args.python
        runtime = engine(python)
        if runtime is None and args.install_runtime:
            venv = root / "runtime" / "python"
            private(venv.parent)
            if not (venv / "bin" / "python").exists():
                subprocess.run([python, "-m", "venv", str(venv)], check=True, timeout=120)
            python = str(venv / "bin" / "python")
            if engine(python) is None:
                subprocess.run([python, "-m", "pip", "--disable-pip-version-check", "install",
                                "--no-input", "--no-cache-dir", "--only-binary=:all:", "duckdb==1.5.6"],
                               check=True, timeout=600)
            runtime = engine(python)
        if runtime is None:
            raise RuntimeError("Python3.11+ with DuckDB1.5.6 is required")
        result["runtime"] = {"executable": python, **runtime}
        native_directory = private(root / "runtime")
        compressed = None
        if args.spatial_extension:
            extension = Path(args.spatial_extension).absolute()
        else:
            compressed = Path(args.spatial_gzip) if args.spatial_gzip else native_directory / "spatial.duckdb_extension.gz"
            if not compressed.exists():
                if not args.acquire_spatial:
                    raise RuntimeError("Original signed spatial extension is required")
                download_extension(compressed)
            result["compressed_extension"] = {"source_url": EXTENSION_URL, **identity(compressed)}
            extension = native_directory / "spatial.duckdb_extension"
            unpack_extension(compressed, extension)
        result["extension"] = {"path": str(extension), **identity(extension)}
        signed_load = subprocess.run([python, "-B", "-c",
            "import duckdb,sys; c=duckdb.connect(); c.execute(\"LOAD '\"+sys.argv[1].replace(\"'\",\"''\")+\"'\"); print(duckdb.__version__)",
            str(extension)], stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=90)
        if signed_load.returncode:
            raise RuntimeError("Native signed extension LOAD failed: " + signed_load.stderr[-5000:])
        result["signed_load"] = signed_load.stdout.strip()
        if args.node:
            subprocess.run([args.node, "--check", str(package / "examples" / "native_spatial_browser.mjs")],
                           check=True, timeout=30)
        operation = private(root / "operation")
        command = [python, "-B", str(package / "examples" / "native_spatial_operation.py"),
                   "--package", str(package), "--original-workspace", str(original),
                   "--operation-dir", str(operation), "--spatial-extension", str(extension)]
        for name in ("chromium", "node", "playwright"):
            value = getattr(args, name)
            if value:
                command.extend(["--" + name, value])
        result.update(state="RECEIVED", command=command)
        save(root / "receiving.json", result)
        print(json.dumps({"state": "RECEIVED", "record": str(root / "receiving.json")}), flush=True)
        completed = subprocess.run(command)
        result.update(state="COMPLETE" if completed.returncode == 0 else "INTERRUPTED",
                      exit_code=completed.returncode, native_result=str(operation / "native-gis-result.json"),
                      finished_at=datetime.now(timezone.utc).isoformat())
        if completed.returncode == 0:
            result["delivery"] = deliver(root, package, Path(args.customer_zip), extension, compressed, Path(args.source_capsule))
        save(root / "receiving.json", result)
        print(json.dumps({"state": result["state"], "record": str(root / "receiving.json"),
                          "delivery": result.get("delivery")}), flush=True)
        return completed.returncode
    except Exception as error:
        result.update(state="INTERRUPTED", error={"type": type(error).__name__, "detail": str(error)},
                      updated_at=datetime.now(timezone.utc).isoformat())
        save(root / "receiving.json", result)
        print(json.dumps({"state": "INTERRUPTED", "record": str(root / "receiving.json"), "error": result["error"]}), flush=True)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import {createRequire} from 'node:module';
import crypto from 'node:crypto';

const config=JSON.parse(await fs.readFile(process.argv[2],'utf8'));
const require=createRequire(path.join(config.node_modules,'package.json'));
const {chromium}=require('playwright');
await fs.mkdir(config.directory,{recursive:true,mode:0o700});
const sha=raw=>crypto.createHash('sha256').update(raw).digest('hex');
const result={schema:'stellar-forge.postgres-semantic-browser.v1',state:'RUNNING',
  started_at:new Date().toISOString(),version_ids:config.version_ids,views:[],downloads:[],screenshots:[],errors:[]};
let browser, page, closePromise, interruption;
const saved=async()=>{
  const temporary=path.join(config.directory,'.receiving-'+process.pid+'.json');
  await fs.writeFile(temporary,JSON.stringify(result,null,2)+'\n',{mode:0o600});
  await fs.rename(temporary,path.join(config.directory,'receiving.json'));
};
async function closeBrowser(){
  if(!browser)return;
  closePromise??=browser.close();
  await closePromise;
  result.browser_closed=true;
}
const handlers=new Map(['SIGTERM','SIGINT','SIGHUP'].map(name=>[name,()=>{
  interruption??=name;
  result.state='INTERRUPTED';result.error='Receiving interrupted by '+interruption;
  if(browser)void closeBrowser().catch(error=>{result.close_error=error.message;});
}]));
for(const [name,handler] of handlers)process.on(name,handler);
const requireValue=(value,message)=>{if(!value)throw new Error(message);};
async function ready(){
  await page.waitForFunction(()=>document.getElementById('database-label')?.textContent.startsWith('PostgreSQL '));
  await page.waitForFunction(()=>!document.getElementById('refresh').disabled);
}
async function idle(){
  await page.waitForFunction(()=>!document.getElementById('refresh').disabled);
  const notice=page.locator('#message[data-level=error]:not([hidden])');
  if(await notice.count())throw new Error(await notice.innerText());
}
async function screen(name){
  await page.locator('[data-screen="'+name+'"]').click();
  await page.locator('#screen-'+name).waitFor({state:'visible'});
}
async function api(route){
  return page.evaluate(async route=>{
    const response=await fetch(route,{headers:{'X-Postgres-Capability':sessionStorage.getItem('postgres-capability')}});
    const value=await response.json();if(!response.ok)throw new Error(value.error);
    return value;
  },route);
}
async function screenshot(name){
  const target=path.join(config.directory,name);
  await page.screenshot({path:target,fullPage:true});
  const raw=await fs.readFile(target);result.screenshots.push({name,bytes:raw.length,sha256:sha(raw)});
}
async function geometry(name){
  const size=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth,body:document.body.scrollWidth}));
  requireValue(size.document<=size.viewport+2&&size.body<=size.viewport+2,'The '+name+' page exceeds its mobile viewport.');
  result.views.push({name,...size});await saved();
}
async function download(button,name,expected){
  const waiting=page.waitForEvent('download');
  await button.click();const received=await waiting;
  const target=path.join(config.directory,name);await received.saveAs(target);
  const raw=await fs.readFile(target);
  if(expected)requireValue(sha(raw)===expected,'Original downloaded dictionary differs.');
  result.downloads.push({name,bytes:raw.length,sha256:sha(raw),suggested_name:received.suggestedFilename()});
  await idle();return JSON.parse(raw.toString('utf8'));
}
async function openEdition(id){
  await screen('editions');
  const choice=page.locator('#edition-list button.item').filter({hasText:id.slice(0,12)});
  while(await choice.count()===0){
    const more=page.locator('#more-editions');
    requireValue(await more.isVisible(),'The original retained edition is absent from the complete browser list: '+id);
    await more.click();await idle();
  }
  await choice.click();
  await page.waitForFunction(id=>document.getElementById('edition-json')?.textContent.includes(id),id);
  await idle();
  await page.locator('#edition-meanings').getByRole('heading',{name:'Original field meanings',exact:true}).waitFor();
}
try{
  browser=await chromium.launch({executablePath:config.chromium,headless:true,
    handleSIGTERM:false,handleSIGINT:false,handleSIGHUP:false,
    args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--renderer-process-limit=1']});
  requireValue(!interruption,'Receiving interrupted by '+interruption);
  page=await browser.newPage({viewport:{width:1440,height:1000},acceptDownloads:true});
  page.setDefaultTimeout(25000);
  page.on('pageerror',error=>result.errors.push(error.message));
  await page.goto(config.url,{waitUntil:'domcontentloaded'});await ready();
  const first=await api('/api/versions/'+config.version_ids[0]);
  requireValue(first.row_count===config.rows&&first.semantics_status==='RETAINED','The original received edition is required.');
  await screen('source');await page.locator('#report-path').fill(config.report);
  await page.getByRole('button',{name:'Inspect delivery',exact:true}).click();
  await page.locator('#source-panel').waitFor({state:'visible'});await idle();
  await page.locator('#source-meanings').getByRole('heading',{name:'Original field meanings',exact:true}).waitFor();
  requireValue(await page.locator('#mapping-rows tr').count()===first.mapping.columns.length,'The source mapping omitted a field.');
  result.views.push({name:'Original source and complete meanings',rows:config.rows,fields:first.mapping.columns.length,viewport:1440});
  await screenshot('source-meanings-desktop.png');
  await openEdition(config.version_ids[0]);
  const dictionary=await download(page.locator('#download-semantics'),'semantics.json',config.dictionary_sha256);
  requireValue(dictionary.sha256===first.semantics.semantic_sha256,'The dictionary semantic identity differs.');
  await page.locator('#edition-meanings').getByText('Original dictionary and source capture',{exact:true}).click();
  await screenshot('retained-meanings-desktop.png');
  await screen('views');await page.locator('#view-name').fill('source_data');
  await page.locator('#view-version').selectOption(config.version_ids[0]);
  await page.getByRole('button',{name:'Review current view and selection',exact:true}).click();
  await page.locator('#view-review').waitFor({state:'visible'});await idle();
  await page.locator('#view-meanings').getByRole('heading',{name:'Original field meanings',exact:true}).waitFor();
  result.views.push({name:'Original selected view and source meanings',viewport:1440});
  await screen('compare');
  await page.locator('#compare-previous').selectOption(config.version_ids[0]);
  await page.locator('#compare-current').selectOption(config.version_ids[1]);
  await page.getByRole('button',{name:'Compare source meanings',exact:true}).click();
  await page.locator('#compare-meaning-result').getByRole('heading',{name:'Source meaning comparison',exact:true}).waitFor();
  await idle();
  const compared=await download(page.locator('#compare-meaning-result').getByRole('button',{name:'Download complete meaning comparison',exact:true}),
    'meaning-comparison.json');
  requireValue(compared.mapping_changed&&!compared.definition_changed&&!compared.capture_changed&&compared.columns.length===1,
    'The original source and alternate receiving alias comparison differs.');
  await screenshot('meaning-comparison-desktop.png');
  await page.setViewportSize({width:390,height:844});
  await geometry('Source meaning comparison');
  await screenshot('meaning-comparison-390px.png');
  await openEdition(config.version_ids[0]);await geometry('Retained edition meanings');
  await screenshot('retained-meanings-390px.png');
  await screen('source');await geometry('Original source mapping and dictionary');
  await screenshot('source-meanings-390px.png');
  await screen('views');await geometry('Application view meanings');
  await screen('recovery');await geometry('Original import operations');
  await page.reload({waitUntil:'domcontentloaded'});await ready();
  const reopened=await api('/api/versions/'+config.version_ids[0]);
  const current=await api('/api/current?name=source_data');
  requireValue(reopened.semantics.file.sha256===config.dictionary_sha256&&
    current.version.version_id===config.version_ids[0],'The original dictionary or selected edition changed on reload.');
  result.reopened={warehouse_id:reopened.warehouse_id,version_id:reopened.version_id,
    semantic_sha256:reopened.semantics.semantic_sha256,selected_revision:current.revision};
  requireValue(result.errors.length===0,'The original browser reported an application error.');
  requireValue(!interruption,'Receiving interrupted by '+interruption);
  result.state='COMPLETE';result.completed_at=new Date().toISOString();
}catch(error){
  result.state=interruption?'INTERRUPTED':'FAILED';
  result.error=interruption?'Receiving interrupted by '+interruption:error.message;
  result.stack=error.stack?.split('\n').slice(0,6);
}finally{
  try{await closeBrowser();}
  catch(error){result.state='FAILED';result.close_error=error.message;result.browser_closed=false;}
  if(!browser)result.browser_closed=false;
  await saved();
  for(const [name,handler] of handlers)process.off(name,handler);
  process.stdout.write(JSON.stringify({state:result.state,result:path.join(config.directory,'receiving.json'),error:result.error})+'\n');
  process.exitCode=result.state==='COMPLETE'?0:1;
}

#!/usr/bin/env python3
"""Explicit customer recovery stages using the installed maintained Python SDK.

The original engine selects the restore path. This example never removes or moves
an existing workspace and never starts purchases, queues or data acquisition.
"""
from __future__ import annotations

import argparse
from dataclasses import asdict
import json
import os
from pathlib import Path

from stellar_forge_buyer import (
    Buyer, BuyerError, DatasetAcquisition, ObjectBuyer,
    StateError, WorkspaceRecovery, WorkspaceRecoveryError,
)


def parser():
    value = argparse.ArgumentParser(description=__doc__, epilog=(
        "Set the chosen passphrase environment variable privately before launch. "
        "Include every native object/dataset directory inside the selected state root; "
        "their existing paths are retained. See ../RECOVERY.md for stopping writers."))
    value.add_argument("stage", choices=("inspect", "snapshot", "verify", "restore", "reopen"))
    value.add_argument("--checkout", required=True, help="Complete original native source/runtime root")
    value.add_argument("--node", default="node")
    value.add_argument("--operator")
    value.add_argument("--state-root")
    value.add_argument("--app-dir", help="Existing Python application directory, distinct from the Node app")
    value.add_argument("--inbox", action="append", default=[])
    value.add_argument("--include", action="append", default=[])
    value.add_argument("--object-session", action="append", default=[], help="Existing native object session directory")
    value.add_argument("--dataset-session", action="append", default=[], help="Existing native dataset session directory")
    value.add_argument("--out")
    value.add_argument("--bundle")
    value.add_argument("--expect", help="Record SHA-256 selected from the existing trusted backup inventory")
    value.add_argument("--pass-env", default="SF88_BACKUP_PASSPHRASE", help="Passphrase variable NAME, never its value")
    value.add_argument("--python", default="/usr/bin/python3", help="Trusted absolute verification interpreter")
    value.add_argument("--quiesced", action="store_true", help="The actual source writers have already been stopped")
    return value


def existing_directory(value, restored_root=None):
    if not value:
        raise StateError("RECOVERY_EXAMPLE_EXISTING_DIRECTORY_REQUIRED")
    path = Path(value)
    if (not path.is_absolute() or not path.is_dir() or path.is_symlink()
            or path.resolve(strict=True) != path):
        raise StateError("RECOVERY_EXAMPLE_EXISTING_DIRECTORY_REQUIRED")
    if restored_root is not None:
        try:
            path.relative_to(restored_root)
        except ValueError:
            raise StateError("RECOVERY_EXAMPLE_PATH_OUTSIDE_RESTORED_ROOT") from None
    return path


def runtime_options(options):
    return dict(checkout=options.checkout, node=options.node, environment=os.environ)


def buyer(options, restored_root=None):
    # Python Buyer creates its directory, so verify existing state FIRST.
    directory = existing_directory(options.app_dir, restored_root)
    return Buyer(state_dir=directory, **runtime_options(options))


def fields(value, names):
    return {name: value[name] for name in names if name in value}


def reopen(options, restored_root=None):
    original = buyer(options, restored_root)
    history = original.history()
    output = {"applicationDirectory": str(original.state_dir),
              "historySchema": history["schema"],
              "operations": [fields(row, ("intentId", "state", "resultRecoverable", "nativeStatus", "deliveryStatus"))
                             for row in history["operations"]],
              "objects": [], "datasets": []}
    for directory in options.object_session:
        path = existing_directory(directory, restored_root)
        session = ObjectBuyer(**runtime_options(options)).open(path)
        view = session.last_report
        accounting = session.accounting()
        output["objects"].append({"native": fields(view.native,
            ("directory", "sessionId", "status", "bytes", "chunkCount")),
            "accounting": accounting.native})
    for directory in options.dataset_session:
        path = existing_directory(directory, restored_root)
        session = DatasetAcquisition(session=path, **runtime_options(options))
        view = session.inspect()
        output["datasets"].append({"native": fields(view,
            ("directory", "sessionId", "status", "snapshot", "rows", "pages", "finalized"))})
    return output


def result_view(result):
    return {"native": result.native, "process": asdict(result.process),
            "completionReported": result.completion_reported}


def main():
    command = parser()
    options = command.parse_args()
    required = {"inspect": ("operator", "state_root"),
                "snapshot": ("operator", "state_root", "out"),
                "verify": ("bundle", "expect"), "restore": ("bundle", "expect"),
                "reopen": ("app_dir",)}[options.stage]
    for name in required:
        if not getattr(options, name):
            command.error("--" + name.replace("_", "-") + " is required for " + options.stage)
    if (options.object_session or options.dataset_session) and not options.app_dir:
        command.error("--app-dir is required when reopening saved sessions")
    if (options.object_session or options.dataset_session) and options.stage not in ("restore", "reopen"):
        command.error("saved session options are only accepted by restore and reopen")
    completed = None
    try:
        if options.stage == "reopen":
            print(json.dumps({"stage": options.stage, "reopened": reopen(options)}, indent=2))
            return 0
        # Standalone recovery does not initialize the missing original state.
        recovery = WorkspaceRecovery(**runtime_options(options))
        if options.stage in ("inspect", "snapshot"):
            if options.app_dir:
                recovery = buyer(options).workspace_recovery()
            selection = dict(directory=options.operator, state_root=options.state_root,
                             inboxes=options.inbox, include=options.include)
            if options.stage == "inspect":
                completed = recovery.inspect(**selection)
            else:
                completed = recovery.snapshot(**selection, output=options.out,
                    quiesced=options.quiesced, passphrase_env=options.pass_env)
        else:
            archive = dict(bundle=options.bundle, expected_record_sha256=options.expect,
                           python=options.python, passphrase_env=options.pass_env)
            completed = recovery.verify(**archive) if options.stage == "verify" else recovery.restore(**archive)
        output = {"stage": options.stage, **result_view(completed)}
        if options.stage == "restore" and options.app_dir:
            output["reopened"] = reopen(options, Path(completed.state_root))
        print(json.dumps(output, indent=2))
        return 0
    except (BuyerError, OSError, ValueError) as error:
        result = error.result if isinstance(error, WorkspaceRecoveryError) else completed
        # Keep original completion visible if a later application read fails.
        print(json.dumps({"error": getattr(error, "code", "RECOVERY_EXAMPLE_FAILED"),
                          "recovery": result_view(result) if result is not None else None}, indent=2))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env node
// MIT. Continue the completed original citation workspace through the Python analyst.
// This is a source-native child command, not another worker or admission controller.
import {parseArgs} from 'node:util';
import {resolve,join,dirname,delimiter,isAbsolute,relative,sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {open,lstat,mkdtemp} from 'node:fs/promises';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import {createHash} from 'node:crypto';
import {startDossierWorkspace} from '../../research-dossiers/server.mjs';
import {openDossierStore} from '../../research-dossiers/dossier.mjs';
import {citationDigest} from '../../research-dossiers/citation-updates.mjs';
import {readResearchHostFile,openResearchSource} from '../../research-dossiers/workspace-files.mjs';
import {privateDirectory,withPrivateLock} from '../../../sf30-seller-sdk/routescan/quota.mjs';
import {need,readJson,writeJson,writeBytes,jsonBytes,parseJson} from '../../node/store.mjs';

const SCHEMA='stellar-forge.python-citation-native-continuation.v1';
const MAX=512*1024*1024;
const same=(a,b)=>citationDigest(a)===citationDigest(b);
async function exists(file){
  try{const stat=await lstat(file);need(stat.isFile()&&!stat.isSymbolicLink(),'PYTHON_CITATION_FILE_INVALID');return true;}
  catch(error){if(error.code==='ENOENT')return false;throw error;}
}
async function pin(file){
  const source=await openResearchSource(file,MAX);
  try{return {file,bytes:source.bytes,sha256:source.sha256};}finally{await source.close();}
}
async function immutable(file,value){
  if(await exists(file)){need(same(await readJson(file,32*1024*1024),value),'PYTHON_CITATION_RECORD_CHANGED');return;}
  try{await writeJson(file,value,{exclusive:true});}
  catch(error){if(error.code!=='EEXIST')throw error;
    need(same(await readJson(file,32*1024*1024),value),'PYTHON_CITATION_RECORD_CHANGED');}
}
function childRun(executable,args,options,signal){
  return new Promise((done,reject)=>{
    const child=spawn(executable,args,options);
    let error=null,stopping=false,timer;
    const stop=()=>{
      if(stopping)return;stopping=true;
      child.kill('SIGTERM');
      timer=setTimeout(()=>child.kill('SIGKILL'),10000);
      timer.unref();
    };
    child.once('error',value=>{error=value;});
    child.once('close',(code,terminated)=>{
      clearTimeout(timer);signal?.removeEventListener('abort',stop);
      if(error)reject(error);else done({exitCode:code,signal:terminated,stopped:stopping});
    });
    if(signal?.aborted)stop();else signal?.addEventListener('abort',stop,{once:true});
  });
}

export async function receiveCompletedCitation({existingRun,directory,checkout,python='python3',
                                                operationId,withWorkbook=false,signal}){
  existingRun=resolve(existingRun);directory=await privateDirectory(resolve(directory));checkout=resolve(checkout);
  need(typeof operationId==='string'&&operationId.length>=8&&operationId.length<=100,
    'PYTHON_CITATION_OPERATION_REQUIRED');
  need(directory!==existingRun&&!relative(existingRun,directory).split(sep).includes('workspace'),
    'PYTHON_CITATION_SEPARATE_CALLER_REQUIRED');
  return withPrivateLock(directory,'native-receiving.lock',async()=>{
    const resultFile=join(existingRun,'result.json'),raw=await readResearchHostFile(resultFile,32*1024*1024);
    const original=parseJson(raw);
    need(original.schema==='sf88-citation-review-workflow.v1'&&original.state==='COMPLETE'&&original.selection,
      'PYTHON_CITATION_COMPLETED_ORIGINAL_REQUIRED');
    const selection=original.selection;
    const sourceFiles={};
    for(const path of [
      'python/examples/research_citation_analyst.mjs','python/examples/research_citation_analyst.py',
      'python/stellar_forge_buyer/research_citations.py','python/stellar_forge_buyer/research_citation_analysis.py',
      'python/research-citation-delivery.mjs','research-dossiers/dossier.mjs','research-dossiers/citation-updates.mjs',
      'research-dossiers/server.mjs','research-dossiers/workspace-client.mjs',
    ]){
      const selected=await pin(join(checkout,'stellar/scf-starforge-20261009/sf88-operator-buyer-cli',path));
      sourceFiles[path]={bytes:selected.bytes,sha256:selected.sha256};
    }
    const binding={schema:SCHEMA,operationId,existingResult:{bytes:raw.length,
      sha256:createHash('sha256').update(raw).digest('hex')},selection,withWorkbook,sourceFiles};
    await immutable(join(directory,'operation.json'),binding);
    if(await exists(join(directory,'complete.json'))){
      const previous=await readJson(join(directory,'complete.json'),32*1024*1024);
      need(same(previous.binding,binding),'PYTHON_CITATION_INPUT_CHANGED');
      for(const artifact of previous.files){
        const checked=await pin(artifact.file);
        need(checked.bytes===artifact.bytes&&checked.sha256===artifact.sha256,'PYTHON_CITATION_OUTPUT_CHANGED');
      }
      return previous;
    }
    const workspace=join(existingRun,'workspace'),store=await openDossierStore(workspace);
    const detail=await store.citationUpdates(selection.dossierId,{
      noticeId:selection.noticeId,revision:selection.currentRevision});
    const review=detail.detail.reviews.find(item=>item.id===selection.reviewId);
    need(review&&review.originalRevision===selection.originalRevision&&review.revision===selection.reviewedRevision,
      'PYTHON_CITATION_SAVED_REVIEW_REQUIRED');
    const request=join(directory,'review-request.original.json');
    await immutable(request,review.request);
    const before=(await store.getMetadata(selection.dossierId)).revision;
    // The caller starts the original listener only after the old complete
    // workflow has closed it. Its own lock refuses another live listener.
    const app=await startDossierWorkspace({directory:workspace,port:0});
    let child,attempt,output,error;
    try{
      attempt=await mkdtemp(join(directory,'attempt-'));
      output=await open(join(attempt,'stdout.json'),'wx',0o600);
      error=await open(join(attempt,'stderr.json'),'wx',0o600);
      need(app.workspaceId===original.merchant?.workspaceId,'PYTHON_CITATION_WORKSPACE_CHANGED');
      const connection=join(attempt,'connection.private.json');
      await writeJson(connection,{schema:'stellar-forge.research-workspace-connection.v1',
        mode:'RESEARCH_DOSSIER_WORKSPACE',directory:workspace,url:app.url,
        workspaceId:app.workspaceId,instanceId:app.instanceId},{exclusive:true});
      const source=join(checkout,'stellar/scf-starforge-20261009/sf88-operator-buyer-cli/python');
      const args=[join(source,'examples/research_citation_analyst.py'),
        '--checkout',checkout,'--node',process.execPath,'--connection',connection,
        '--directory',join(directory,'analyst'),'--workspace-id',app.workspaceId,
        '--dossier',selection.dossierId,'--request-file',request,'--operation-id',operationId,
        '--current-revision',String(selection.currentRevision),'--wait-seconds','900',
        ...(withWorkbook?['--with-workbook']:[])];
      child=await childRun(python,args,{cwd:directory,env:{...process.env,
        PYTHONPATH:[source,process.env.PYTHONPATH].filter(Boolean).join(delimiter)},
        stdio:['ignore',output.fd,error.fd]},signal);
      await immutable(join(attempt,'outcome.json'),child);
    }finally{
      await Promise.allSettled([output?.close(),error?.close()]);
      await app.close();
    }
    need(child?.exitCode===0&&!child.stopped,'PYTHON_CITATION_CHILD_INCOMPLETE');
    const result=await readJson(join(directory,'analyst','complete.json'),32*1024*1024);
    need(result.state==='COMPLETE'&&result.reviewId===selection.reviewId&&
      result.originalRevision===selection.originalRevision&&result.reviewedRevision===selection.reviewedRevision&&
      result.currentRevision===selection.currentRevision&&result.originalHeadUnchanged&&
      result.exactSavedRequestRecovered&&(!withWorkbook||result.workbook),
      'PYTHON_CITATION_RECEIVING_INCOMPLETE');
    need((await store.getMetadata(selection.dossierId)).revision===before,'PYTHON_CITATION_ORIGINAL_HEAD_CHANGED');
    const files=[];
    for(const artifact of result.files){
      need(typeof artifact.file==='string'&&isAbsolute(artifact.file)&&
        relative(join(directory,'analyst'),artifact.file)&&
        !relative(join(directory,'analyst'),artifact.file).split(sep).includes('..')&&
        !artifact.file.split(sep).some(part=>['connection.json','connection.private.json'].includes(part)),
        'PYTHON_CITATION_PRIVATE_OUTPUT_REFUSED');
      const checked=await pin(artifact.file);
      need(checked.bytes===artifact.bytes&&checked.sha256===artifact.sha256,'PYTHON_CITATION_OUTPUT_CHANGED');
      files.push(checked);
    }
    files.push(await pin(join(directory,'analyst','complete.json')));
    const completed={schema:SCHEMA,state:'COMPLETE',binding,workspaceId:app.workspaceId,
      reviewId:selection.reviewId,selection,files};
    await immutable(join(directory,'complete.json'),completed);
    return completed;
  });
}
async function main(){
  const {values}=parseArgs({options:{
    'existing-run':{type:'string'},directory:{type:'string'},checkout:{type:'string'},
    python:{type:'string',default:'python3'},'operation-id':{type:'string'},
    'with-workbook':{type:'boolean',default:false},help:{type:'boolean',short:'h',default:false}
  }});
  if(values.help){
    process.stdout.write('Receive an already completed original citation review through Python.\n'+
      'Usage: research-citation-python-receive --existing-run DIR --directory NEW_DIR --checkout SOURCE\n'+
      '  --operation-id ORIGINAL_CONTINUATION_ID [--python EXISTING_PYTHON] [--with-workbook]\n'+
      'Uses the saved review, original listener/readers and Python call history; no provider request is created.\n');
    return;
  }
  for(const name of ['existing-run','directory','checkout','operation-id'])
    need(values[name],'PYTHON_CITATION_ARGUMENT_REQUIRED');
  const controller=new AbortController(),stop=()=>controller.abort();
  process.once('SIGINT',stop);process.once('SIGTERM',stop);
  try{
    const result=await receiveCompletedCitation({existingRun:values['existing-run'],directory:values.directory,
      checkout:values.checkout,python:values.python,operationId:values['operation-id'],
      withWorkbook:values['with-workbook'],signal:controller.signal});
    process.stdout.write(JSON.stringify(result)+'\n');
  }catch(error){
    process.stderr.write(JSON.stringify({state:'INCOMPLETE',error:error.code??error.name})+'\n');
    process.exitCode=1;
  }finally{process.removeListener('SIGINT',stop);process.removeListener('SIGTERM',stop);}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))await main();

#!/usr/bin/env node
// MIT. Complete customer delivery on the original, already running Research workspace.
import {parseArgs} from 'node:util';
import {resolve,join,delimiter,isAbsolute} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawn} from 'node:child_process';

const BUYER='stellar/scf-starforge-20261009/sf88-operator-buyer-cli';
const MAX_OUTPUT=16*1024*1024;
const need=(value,code)=>{if(!value)throw Object.assign(new Error(code),{code});};
const absolute=(value)=>{need(typeof value==='string'&&isAbsolute(value),'ELIGIBILITY_CUSTOMER_ABSOLUTE_PATH_REQUIRED');return resolve(value);};

/** Attach to the existing original listener; its owner retains lifecycle authority. */
export async function receiveEligibilityCustomer({
  checkout,connection,directory,dossierId,reviewId,operationId,revision,workSetId,workspaceId,
  python='python3',node=process.execPath,timeout=900,replayRequests=[],signal
}={}){
  checkout=absolute(checkout);connection=absolute(connection);directory=absolute(directory);
  need(typeof dossierId==='string'&&typeof reviewId==='string'&&typeof operationId==='string',
    'ELIGIBILITY_CUSTOMER_SELECTION_REQUIRED');
  need(Number.isSafeInteger(timeout)&&timeout>=1&&timeout<=3600,'ELIGIBILITY_CUSTOMER_TIMEOUT_INVALID');
  need(revision===undefined||Number.isSafeInteger(revision)&&revision>=1,'ELIGIBILITY_CUSTOMER_REVISION_INVALID');
  need(Array.isArray(replayRequests),'ELIGIBILITY_CUSTOMER_REQUEST_FILES_INVALID');
  need(!signal?.aborted,'ELIGIBILITY_CUSTOMER_CANCELLED_BEFORE_START');
  const source=join(checkout,BUYER,'python'),args=[
    join(source,'examples/research_eligibility_customer.py'),'--checkout',checkout,
    '--connection',connection,'--directory',directory,'--dossier-id',dossierId,
    '--review-id',reviewId,'--operation-id',operationId,'--node',node,'--timeout',String(timeout),
    ...(revision!==undefined?['--revision',String(revision)]:[]),
    ...(workSetId?['--work-set-id',workSetId]:[]),...(workspaceId?['--workspace-id',workspaceId]:[]),
    ...replayRequests.flatMap(file=>['--replay-request',absolute(file)])
  ];
  const group=process.platform!=='win32';
  const result=await new Promise((done,reject)=>{
    const child=spawn(python,args,{cwd:checkout,env:{...process.env,
      PYTHONPATH:[source,process.env.PYTHONPATH].filter(Boolean).join(delimiter)},
      detached:group,stdio:['ignore','pipe','pipe']});
    const chunks={stdout:[],stderr:[]},sizes={stdout:0,stderr:0};
    let problem=null,stopping=false,timer;
    const terminate=kind=>{
      if(!child.pid)return;
      try{if(group)process.kill(-child.pid,kind);else child.kill(kind);}
      catch(error){if(error.code!=='ESRCH')problem??=error;}
    };
    const stop=()=>{
      if(stopping)return;stopping=true;terminate('SIGTERM');
      timer=setTimeout(()=>terminate('SIGKILL'),10000);timer.unref();
    };
    for(const name of ['stdout','stderr'])child[name].on('data',chunk=>{
      sizes[name]+=chunk.length;
      if(sizes[name]>MAX_OUTPUT){problem??=Object.assign(new Error('ELIGIBILITY_CUSTOMER_OUTPUT_LIMIT'),
        {code:'ELIGIBILITY_CUSTOMER_OUTPUT_LIMIT'});stop();return;}
      chunks[name].push(chunk);
    });
    child.once('error',error=>{problem=error;});
    child.once('close',(code,terminated)=>{
      clearTimeout(timer);signal?.removeEventListener('abort',stop);
      if(problem){reject(problem);return;}
      const stdout=Buffer.concat(chunks.stdout).toString('utf8'),stderr=Buffer.concat(chunks.stderr).toString('utf8');
      let value,error;try{value=JSON.parse(stdout);}catch{}
      try{error=JSON.parse(stderr);}catch{}
      if(code!==0||stopping||value?.state!=='COMPLETE'){
        reject(Object.assign(new Error(error?.error??'ELIGIBILITY_CUSTOMER_INCOMPLETE'),
          {code:error?.error??'ELIGIBILITY_CUSTOMER_INCOMPLETE',exitCode:code,signal:terminated}));return;
      }
      try{
        need(value.schema==='stellar-forge.research-eligibility-customer.v1'&&
          value.selection?.dossierId===dossierId&&value.selection.reviewId===reviewId&&
          (revision===undefined||value.selection.revision===revision)&&
          value.file===join(directory,'complete.json')&&value.archive?.file===join(directory,'Eligibility_Delivery.zip'),
          'ELIGIBILITY_CUSTOMER_RECEIPT_CHANGED');
        done(value);
      }catch(error){reject(error);}
    });
    if(signal?.aborted)stop();else signal?.addEventListener('abort',stop,{once:true});
  });
  return result;
}

export async function main(argv=process.argv.slice(2),{output=process.stdout}={}){
  const {values}=parseArgs({args:argv,options:{
    checkout:{type:'string'},connection:{type:'string'},directory:{type:'string'},
    'dossier-id':{type:'string'},'review-id':{type:'string'},'operation-id':{type:'string'},
    revision:{type:'string'},'work-set-id':{type:'string'},'workspace-id':{type:'string'},
    python:{type:'string',default:'python3'},node:{type:'string',default:process.execPath},
    timeout:{type:'string',default:'900'},'replay-request':{type:'string',multiple:true},
    help:{type:'boolean',short:'h',default:false}
  },strict:true});
  if(values.help){
    output.write('Deliver a saved original eligibility review through Python and complete customer receiving.\n'+
      'Usage: research-eligibility-customer --checkout SOURCE --connection PRIVATE_CONNECTION.json\n'+
      '  --directory CUSTOMER_DIRECTORY --dossier-id ORIGINAL_ID --review-id ORIGINAL_REVIEW\n'+
      '  --operation-id ORIGINAL_CONTINUATION [--revision N] [--work-set-id ORIGINAL_WORKSET]\n'+
      '  [--workspace-id ORIGINAL_WORKSPACE] [--python EXISTING_PYTHON] [--node EXISTING_NODE]\n'+
      '  [--replay-request ORIGINAL_COMMITTED_REQUEST.json ...] [--timeout SECONDS]\n'+
      'The existing listener stays with its owner. Outputs include all twelve complete files,\n'+
      'the original JSON/gzip receivers, exact ZIP and independent editable receiving.\n');
    return;
  }
  const controller=new AbortController(),stop=()=>controller.abort();
  process.once('SIGINT',stop);process.once('SIGTERM',stop);
  try{
    const value=await receiveEligibilityCustomer({
      checkout:values.checkout,connection:values.connection,directory:values.directory,
      dossierId:values['dossier-id'],reviewId:values['review-id'],operationId:values['operation-id'],
      revision:values.revision===undefined?undefined:Number(values.revision),
      workSetId:values['work-set-id'],workspaceId:values['workspace-id'],
      python:values.python,node:values.node,timeout:Number(values.timeout),
      replayRequests:values['replay-request']??[],signal:controller.signal
    });output.write(JSON.stringify(value)+'\n');return value;
  }finally{process.removeListener('SIGINT',stop);process.removeListener('SIGTERM',stop);}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{await main();}catch(error){process.stderr.write(JSON.stringify({state:'INCOMPLETE',error:error.code??error.name})+'\n');process.exitCode=1;}
}

#!/usr/bin/env node
/**
 * Original Analysis browser continuation over one existing Research selection.
 *
 * The caller supplies a live original Analysis host and an owned Playwright
 * Page. Source capture, mapping, preview and import use the real browser
 * controls. Full exports/workbook/portable receiving stay in the original
 * research_document_workbook.py workflow.
 */
import {createHash, randomUUID} from 'node:crypto';
import {mkdir, open, readFile, rename, unlink} from 'node:fs/promises';
import {dirname, join, resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

const SCHEMA='stellar-forge.analysis-research-browser-receiving.v1';
const canonical=value=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?
  Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
const same=(left,right)=>JSON.stringify(canonical(left))===JSON.stringify(canonical(right));
const need=(value,code)=>{if(!value)throw Object.assign(new Error(code),{code});};
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
async function readJson(path){try{return JSON.parse(await readFile(path,'utf8'));}catch(error){if(error.code==='ENOENT')return null;throw error;}}
async function publish(path,value){
  await mkdir(dirname(path),{recursive:true,mode:0o700});
